/* ============================================================
   PATCH v1.3.7 — Спойлер для списка ответственных
   ============================================================ */
.hyp-people-details {
    margin-top: 10px !important;
    border: 1px solid var(--trk-input-border) !important;
    border-radius: 8px !important;
    background: var(--trk-input-bg) !important;
    padding: 0 !important;
    overflow: hidden !important;
}

.hyp-people-details summary.hyp-people-label {
    padding: 8px 12px !important;
    cursor: pointer !important;
    user-select: none !important;
    outline: none !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    margin: 0 !important;
    font-size: 0.8rem !important;
    font-weight: 700 !important;
    color: var(--trk-text) !important;
    text-transform: none !important;
    letter-spacing: 0 !important;
}

.hyp-people-details summary::-webkit-details-marker { display: none !important; }

.hyp-people-details summary::before {
    content: '▶' !important;
    font-size: 0.65em !important;
    transition: transform 0.15s !important;
    color: var(--trk-meta) !important;
}

.hyp-people-details[open] summary::before {
    transform: rotate(90deg) !important;
}

.hyp-people-count {
    background: var(--trk-filter-active-bg) !important;
    color: var(--trk-filter-active) !important;
    font-size: 0.7rem !important;
    padding: 1px 8px !important;
    border-radius: 10px !important;
    margin-left: auto !important;
    font-weight: 800 !important;
}

.hyp-people-details .hyp-people-list {
    border: none !important;
    border-top: 1px dashed var(--trk-border-soft) !important;
    border-radius: 0 0 8px 8px !important;
    max-height: 200px !important;
    background: transparent !important;
}

body.trk-theme-light .hyp-people-details {
    background: #ffffff !important;
    border-color: rgba(0,0,0,0.15) !important;
}
